import React, { useState, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "../ui/dialog";
import { Button } from "../ui/button";
import { Input } from "../ui/input";
import { Label } from "../ui/label";
import { Textarea } from "../ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../ui/select";
import { Upload, File, X } from "lucide-react";
import { clientService } from "../../services/clientService";
import { projectService } from "../../services/projectService";
import { documentService } from "../../services/documentService";

export const UploadDocumentModal = ({ isOpen, onClose, onSuccess }) => {
  const [formData, setFormData] = useState({
    title: "",
    description: "",
    document_type: "report",
    project_id: "",
    client_id: "",
    is_public: false,
  });
  const [file, setFile] = useState(null);
  const [loading, setLoading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [clients, setClients] = useState([]);
  const [projects, setProjects] = useState([]);
  const [allProjects, setAllProjects] = useState([]);

  useEffect(() => {
    if (isOpen) {
      loadClients();
      loadProjects();
    }
  }, [isOpen]);

  const loadClients = async () => {
    try {
      const data = await clientService.getAll();
      setClients(data);
    } catch (error) {
      console.error("Error loading clients:", error);
    }
  };

  const loadProjects = async () => {
    try {
      const data = await projectService.getAll();
      setAllProjects(data);
      setProjects(data);
    } catch (error) {
      console.error("Error loading projects:", error);
    }
  };

  const handleClientChange = (clientId) => {
    setFormData({ ...formData, client_id: clientId, project_id: "" });

    if (clientId) {
      const filteredProjects = allProjects.filter(
        (p) => p.client_id?._id === clientId || p.client_id === clientId
      );
      setProjects(filteredProjects);
    } else {
      setProjects(allProjects);
    }
  };

  const handleFileChange = (e) => {
    const selectedFile = e.target.files[0];
    if (selectedFile) {
      // Validar tamaño (10MB max)
      if (selectedFile.size > 10485760) {
        alert("El archivo es demasiado grande. Máximo 10MB");
        return;
      }

      // Validar tipo
      const allowedTypes = [
        "application/pdf",
        "application/msword",
        "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        "application/vnd.ms-excel",
        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        "image/jpeg",
        "image/png",
      ];

      if (!allowedTypes.includes(selectedFile.type)) {
        alert(
          "Tipo de archivo no permitido. Use: PDF, DOC, DOCX, XLS, XLSX, JPG, PNG"
        );
        return;
      }

      setFile(selectedFile);

      // Auto-llenar título si está vacío
      if (!formData.title) {
        setFormData({
          ...formData,
          title: selectedFile.name.replace(/\.[^/.]+$/, ""),
        });
      }
    }
  };

  const handleRemoveFile = () => {
    setFile(null);
    document.getElementById("file-input").value = "";
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!file) {
      alert("Por favor seleccione un archivo");
      return;
    }

    setLoading(true);
    setUploadProgress(0);

    try {
      const formDataToSend = new FormData();
      formDataToSend.append("file", file);
      formDataToSend.append("title", formData.title);
      formDataToSend.append("description", formData.description);
      formDataToSend.append("document_type", formData.document_type);
      formDataToSend.append("is_public", formData.is_public);

      if (formData.project_id) {
        formDataToSend.append("project_id", formData.project_id);
      }
      if (formData.client_id) {
        formDataToSend.append("client_id", formData.client_id);
      }

      await documentService.upload(formDataToSend, (progressEvent) => {
        const percentCompleted = Math.round(
          (progressEvent.loaded * 100) / progressEvent.total
        );
        setUploadProgress(percentCompleted);
      });

      alert("Documento subido exitosamente");
      onSuccess();
      handleClose();
    } catch (error) {
      console.error("Error uploading document:", error);
      alert(error.response?.data?.detail || "Error al subir documento");
    } finally {
      setLoading(false);
      setUploadProgress(0);
    }
  };

  const handleClose = () => {
    setFormData({
      title: "",
      description: "",
      document_type: "report",
      project_id: "",
      client_id: "",
      is_public: false,
    });
    setFile(null);
    setUploadProgress(0);
    onClose();
  };

  return (
    <Dialog open={isOpen} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-[600px] max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Subir Documento</DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit}>
          <div className="space-y-4 py-4">
            {/* Selección de archivo */}
            <div>
              <Label htmlFor="file-input">Archivo *</Label>
              <div className="mt-2">
                {!file ? (
                  <label
                    htmlFor="file-input"
                    className="flex flex-col items-center justify-center w-full h-32 border-2 border-dashed border-gray-300 rounded-lg cursor-pointer hover:border-green-500 transition-colors"
                  >
                    <Upload className="w-8 h-8 text-gray-400 mb-2" />
                    <span className="text-sm text-gray-600">
                      Click para seleccionar archivo
                    </span>
                    <span className="text-xs text-gray-500 mt-1">
                      PDF, DOC, DOCX, XLS, XLSX, JPG, PNG (Max 10MB)
                    </span>
                  </label>
                ) : (
                  <div className="flex items-center justify-between p-4 bg-green-50 border border-green-200 rounded-lg">
                    <div className="flex items-center space-x-3">
                      <File className="w-8 h-8 text-green-600" />
                      <div>
                        <p className="text-sm font-medium text-gray-900">
                          {file.name}
                        </p>
                        <p className="text-xs text-gray-500">
                          {(file.size / 1024 / 1024).toFixed(2)} MB
                        </p>
                      </div>
                    </div>
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      onClick={handleRemoveFile}
                    >
                      <X className="w-4 h-4" />
                    </Button>
                  </div>
                )}
                <input
                  id="file-input"
                  type="file"
                  className="hidden"
                  onChange={handleFileChange}
                  accept=".pdf,.doc,.docx,.xls,.xlsx,.jpg,.jpeg,.png"
                />
              </div>
            </div>

            {/* Barra de progreso */}
            {loading && uploadProgress > 0 && (
              <div className="w-full bg-gray-200 rounded-full h-2">
                <div
                  className="bg-green-600 h-2 rounded-full transition-all duration-300"
                  style={{ width: `${uploadProgress}%` }}
                />
                <p className="text-xs text-center text-gray-600 mt-1">
                  {uploadProgress}% subido
                </p>
              </div>
            )}

            {/* Título */}
            <div>
              <Label htmlFor="title">Título *</Label>
              <Input
                id="title"
                value={formData.title}
                onChange={(e) =>
                  setFormData({ ...formData, title: e.target.value })
                }
                required
                placeholder="Nombre del documento"
              />
            </div>

            {/* Descripción */}
            <div>
              <Label htmlFor="description">Descripción</Label>
              <Textarea
                id="description"
                value={formData.description}
                onChange={(e) =>
                  setFormData({ ...formData, description: e.target.value })
                }
                placeholder="Descripción del documento..."
                rows={3}
              />
            </div>

            {/* Tipo de documento */}
            <div>
              <Label htmlFor="document_type">Tipo de Documento *</Label>
              <Select
                value={formData.document_type}
                onValueChange={(value) =>
                  setFormData({ ...formData, document_type: value })
                }
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="report">Reporte</SelectItem>
                  <SelectItem value="certification">Certificación</SelectItem>
                  <SelectItem value="manual">Manual</SelectItem>
                  <SelectItem value="permit">Permiso</SelectItem>
                </SelectContent>
              </Select>
            </div>

            {/* Cliente */}
            <div>
              <Label htmlFor="client_id">Cliente (Opcional)</Label>
              <Select
                value={formData.client_id}
                onValueChange={handleClientChange}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Seleccionar cliente..." />
                </SelectTrigger>
                <SelectContent>
                  {clients.map((client) => (
                    <SelectItem key={client._id} value={client._id}>
                      {client.company_name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              {formData.client_id && (
                <Button
                  type="button"
                  variant="ghost"
                  size="sm"
                  onClick={() => handleClientChange("")}
                  className="mt-1 text-xs"
                >
                  Limpiar selección
                </Button>
              )}
            </div>

            {/* Proyecto */}
            <div>
              <Label htmlFor="project_id">Proyecto (Opcional)</Label>
              <Select
                value={formData.project_id}
                onValueChange={(value) =>
                  setFormData({ ...formData, project_id: value })
                }
                disabled={projects.length === 0}
              >
                <SelectTrigger>
                  <SelectValue
                    placeholder={
                      projects.length === 0
                        ? "Seleccione un cliente primero"
                        : "Seleccionar proyecto..."
                    }
                  />
                </SelectTrigger>
                <SelectContent>
                  {projects.map((project) => (
                    <SelectItem key={project._id} value={project._id}>
                      {project.project_name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              {formData.project_id && (
                <Button
                  type="button"
                  variant="ghost"
                  size="sm"
                  onClick={() => setFormData({ ...formData, project_id: "" })}
                  className="mt-1 text-xs"
                >
                  Limpiar selección
                </Button>
              )}
            </div>

            {/* Público */}
            <div className="flex items-center space-x-2">
              <input
                type="checkbox"
                id="is_public"
                checked={formData.is_public}
                onChange={(e) =>
                  setFormData({ ...formData, is_public: e.target.checked })
                }
                className="w-4 h-4 text-green-600 rounded focus:ring-green-500"
              />
              <Label htmlFor="is_public" className="cursor-pointer">
                Documento público (visible para todos)
              </Label>
            </div>
          </div>

          <DialogFooter>
            <Button type="button" variant="outline" onClick={handleClose}>
              Cancelar
            </Button>
            <Button
              type="submit"
              disabled={loading || !file}
              className="bg-green-600 hover:bg-green-700"
            >
              {loading ? "Subiendo..." : "Subir Documento"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
};
